import crypto from "node:crypto";
import fs from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import { Readable, Transform } from "node:stream";
import { pipeline } from "node:stream/promises";
import { env } from "../../config/env.js";
import { ApiError } from "../../utils/api-error.js";

/**
 * Where file contents live. Only a local-disk provider exists today; a bucket
 * provider would implement the same interface. Keys are always generated by
 * the server, never taken from a client.
 */
export interface StorageProvider {
    name: string;
    write(key: string, body: Readable, maxBytes: number): Promise<{ size: number; sha256: string; head: Buffer }>;
    read(key: string, range?: { start: number; end: number }): Readable;
    size(key: string): Promise<number>;
    remove(key: string): Promise<void>;
    localPath(key: string): string;
}

const SNIFF_BYTES = 64;

class LocalDiskStorage implements StorageProvider {
    name = "local";

    constructor(private readonly root: string) {}

    localPath(key: string) {
        const full = path.resolve(this.root, key);
        if (!full.startsWith(path.resolve(this.root) + path.sep)) {
            throw new Error("Storage key escapes the storage directory");
        }
        return full;
    }

    async write(key: string, body: Readable, maxBytes: number) {
        const target = this.localPath(key);
        await fsp.mkdir(path.dirname(target), { recursive: true });
        const hash = crypto.createHash("sha256");
        let size = 0;
        let head = Buffer.alloc(0);

        const meter = new Transform({
            transform(chunk: Buffer, _encoding, callback) {
                size += chunk.length;
                if (size > maxBytes) {
                    callback(new ApiError(413, "FILE_TOO_LARGE", "The file is larger than declared or allowed"));
                    return;
                }
                if (head.length < SNIFF_BYTES) head = Buffer.concat([head, chunk.subarray(0, SNIFF_BYTES - head.length)]);
                hash.update(chunk);
                callback(null, chunk);
            },
        });

        try {
            await pipeline(body, meter, fs.createWriteStream(target, { mode: 0o600 }));
        } catch (error) {
            await fsp.rm(target, { force: true });
            throw error;
        }
        return { size, sha256: hash.digest("hex"), head };
    }

    read(key: string, range?: { start: number; end: number }) {
        return fs.createReadStream(this.localPath(key), range);
    }

    async size(key: string) {
        return (await fsp.stat(this.localPath(key))).size;
    }

    async remove(key: string) {
        await fsp.rm(this.localPath(key), { force: true });
    }
}

let provider: StorageProvider = new LocalDiskStorage(path.resolve(env.media.localDir));

export const storage = () => provider;

/** Tests point storage at a temporary directory. */
export const useStorageDirectory = (directory: string) => {
    provider = new LocalDiskStorage(directory);
};

export const newStorageKey = (suffix = "") => {
    const now = new Date();
    return `${now.getUTCFullYear()}/${String(now.getUTCMonth() + 1).padStart(2, "0")}/${crypto.randomUUID()}${suffix}`;
};
